/** getMapIdBySerial **/
SELECT map_id
FROM device_map dm
WHERE device_id = #{deviceId}

/** getDeviceIdBySerial **/
SELECT id
FROM device
WHERE serial = #{serial}
  AND linked_yn = 'Y'

/** getScheduleTypeCode **/
SELECT schedule_type_code
FROM reserve_clean
WHERE id = #{scheduleId}

select area_id as areaId
from device_map
where map_id = #{mapId}
